entries[60866] = { ["name"] = "Feuerstuhl", ["text"] = "Wirken in 3.5 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nTitanstahlbarren (12), Eine Handvoll Kobaltbolzen (40), Arktischer Pelz (2), Geborgene Dunkeleisenteile , Goblinmaschinenkolben (8), Elementiumveredelter Auspuff\nVerkäufer:\nGara Schädelberster\nZone:\nBoreanische Tundra\nExpedition der Horde - Ehrfürchtig\nKosten:\n400\n\nVerkäufer:\nSebastian Kranich\nZone:\nDer Heulende Fjord\nVerkäufer:\nExpedition der Horde - Ehrfürchtig\nKosten:\n400\n\nHorde\nFeuerstuhl\nReittier (Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man diesen heißen Ofen fährt.\nBeschwört einen echt heißen Ofen oder parkt ihn.\n1 - 80 ( 80)\nBenötigt Unerfahrenes Reiten\n\"Wenn sie auch schwer zu bauen und zu pflegen sind, machen diese Feuerstühle den Aufwand durch schiere Großartigkeit wett.\"\nBeruf:\nIngenieurskunst\nAllianz\nChopper des Robogenieurs\nReittier (Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man diesen Chopper fährt.\nBeschwört einen echt fetten Chopper des Robogenieurs oder parkt ihn.\n1 - 80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dank ausgezeichneter Ingenieurskunst ist dieser Chopper eines der wenigen privaten Fahrzeuge in Azeroth, das zwei Personen befördern kann.\"\nBeruf:\nIngenieurskunst" }
entries[60867] = { ["name"] = "Chopper des Robogenieurs", ["text"] = "Wirken in 3.5 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nTitanstahlbarren (12), Eine Handvoll Kobaltbolzen (40), Arktischer Pelz (2), Geborgene Dunkeleisenteile , Goblinmaschinenkolben (8), Elementiumveredelter Auspuff\nVerkäufer:\nLogistikoffizier Heller\nZone:\nDer Heulende Fjord\nVorhut der Allianz - Ehrfürchtig\nKosten:\n400\n\nVerkäufer:\nLogistikoffizierin Silberstein\nZone:\nBoreanische Tundra\nVorhut der Allianz - Ehrfürchtig\nKosten:\n400\n\nAllianz\nChopper des Robogenieurs\nReittier (Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man diesen Chopper fährt.\nBeschwört einen echt fetten Chopper des Robogenieurs oder parkt ihn.\n1 - 80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dank ausgezeichneter Ingenieurskunst ist dieser Chopper eines der wenigen privaten Fahrzeuge in Azeroth, das zwei Personen befördern kann.\"\nBeruf:\nIngenieurskunst\nHorde\nFeuerstuhl\nReittier (Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man diesen heißen Ofen fährt.\nBeschwört einen echt heißen Ofen oder parkt ihn.\n1 - 80 ( 80)\nBenötigt Unerfahrenes Reiten\n\"Wenn sie auch schwer zu bauen und zu pflegen sind, machen diese Feuerstühle den Aufwand durch schiere Großartigkeit wett.\"\nBeruf:\nIngenieurskunst" }
