entries[60969] = { ["name"] = "Fliegender Teppich", ["text"] = "Wirken in 3.5 sek. 5\nReagenzien:\nMagieerfüllter Froststoffballen (6), Vereiste Spinnenseide (4), Grüner Farbstoff (4), Schwerer Seidenfaden (5)\nBerufsausbilder:\nSchneiderei von Nordend (1)\nKosten:\n10\n\nFliegender Teppich\nReittier (Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen fliegenden Teppich oder gibt ihn wieder frei. Dieses Fortbewegungsmittel passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n1 - 80 ( 80)\nBenötigt Schneiderei von Nordend\n(1)\nBenötigt Unerfahrenes Reiten\n\n\"Schwingt Euch auf diesen fliegenden Teppich, um Azeroth schwebend, taumelnd und wiegend zu erkunden.\"\nBeruf:\nSchneiderei" }
entries[60971] = { ["name"] = "Großartiger fliegender Teppich", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nMagieerfüllter Froststoffballen (12), Monarchentopas (4), Roter Farbstoff (4), Gelber Farbstoff (2), Vereiste Spinnenseide (4)\nBerufsausbilder:\nSchneiderei von Nordend (50)\nKosten:\n2\n\nGroßartiger fliegender Teppich\nWird beim Aufheben gebunden\nReittier (Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen großartigen fliegenden Teppich oder gibt ihn wieder frei. Dieses Fortbewegungsmittel passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n1 - 80 ( 80)\nBenötigt Schneiderei von Nordend\n(1)\nBenötigt Unerfahrenes Reiten\n\n\"Standardfunktionen sind unter anderem: ein stabiler, mit Froststoff erfüllter Rahmen und eine Naht aus echter vereister Spinnenseide. Kopfstütze separat erhältlich.\"\nBeruf:\nSchneiderei" }
